https://www.saudiexchange.sa/wps/tadawul.eportal.CompanyProfilev2/js/saudiCable.js 754:8 "**foreign gara" function foreignGraph(fr) {
		
		// Make monochrome colors
		var pieColors = (function () {
			var colors = [],
				base = Highcharts.getOptions().colors[0],
				i;

			for (i = 0; i < 10; i += 1) {
				// Start out with a darkened base color (negative brighten), and end
				// up with a much brighter color
				colors.push(
					Highcharts.color(base)
						.brighten((i - 2) / 10)
						.get()
				);
			}
			return colors;
		})();

		// Build the chart
		Highcharts.chart('foreignGraph', {
			chart: {
				plotBackgroundColor: null,
				plotBorderWidth: null,
				plotShadow: false,
				type: 'pie',
			},
			title: {
				text: 'Browser market shares at a specific website, 2014',
			},
			tooltip: {
				pointFormat: '{series.name}: <b>{point.percentage:.1f}%</b>',
			},
			accessibility: {
				point: {
					valueSuffix: '%',
				},
			},
			plotOptions: {
				pie: {
					allowPointSelect: true,
					cursor: 'pointer',
					colors: pieColors,
					dataLabels: {
						enabled: true,
						format: '<b>{point.name}</b><br>{point.percentage:.1f} %',
						distance: -50,
						filter: {
							property: 'percentage',
							operator: '>',
							value: 4,
						},
					},
				},
			},
			series: [
				{
					name: 'Share',
					data:fr,
				},
			],
		});
	}
